'use client';

import { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';
import Link from 'next/link';
import type { ReviewResponse, ReviewCompleted, ReviewClause, FairnessRating } from '@/app/evaluate-contract/types';
import { ReviewResponseSchema } from '@/app/evaluate-contract/types';
import { FAIRNESS_SECTION_ORDER } from '@/app/evaluate-contract/fairness-utils';
import { LoadingShimmer } from '@/app/evaluate-contract/LoadingShimmer';
import { BACKEND_URL, POLL_INTERVAL, POLL_TIMEOUT, STATUS_TEXT } from '@/app/evaluate-contract/constants';
import ScoreBadge from './ScoreBadge';
import ClauseSection from './ClauseSection';

const PAGE_CONTAINER = 'mx-auto max-w-2xl px-4 py-12';
const PAGE_TITLE = 'text-3xl font-bold tracking-tight';
const BACK_LINK = 'mt-6 inline-block text-sm text-foreground/60 underline hover:text-foreground';

function LoadingState({ statusText }: { statusText: string }) {
  return (
    <div className={PAGE_CONTAINER}>
      <h1 className={PAGE_TITLE}>Evaluating contract</h1>
      <div className="mt-6">
        <LoadingShimmer statusText={statusText} />
      </div>
    </div>
  );
}

function groupByFairness(clauses: ReviewClause[]) {
  return clauses.reduce<Record<FairnessRating, ReviewClause[]>>(
    (groups, clause) => {
      groups[clause.fairness].push(clause);
      return groups;
    },
    { dealbreaker: [], 'non-standard': [], fair: [] },
  );
}

function NoEvaluation() {
  return (
    <div className={PAGE_CONTAINER}>
      <h1 className={PAGE_TITLE}>No evaluation found</h1>
      <p className="mt-2 text-foreground/60">This evaluation may have expired or the link is invalid.</p>
      <Link href="/evaluate-contract" className={BACK_LINK}>
        Evaluate a contract
      </Link>
    </div>
  );
}

function EvaluationResults({ result }: { result: ReviewCompleted }) {
  const grouped = groupByFairness(result.clauses);

  return (
    <article className={PAGE_CONTAINER}>
      <h1 className={PAGE_TITLE}>Evaluation complete</h1>
      {result.overall_fairness && (
        <div className="mt-4">
          <ScoreBadge rating={result.overall_fairness} />
        </div>
      )}
      {result.summary && <p className="mt-3 text-foreground/60">{result.summary}</p>}
      {result.call_to_action && (
        <ul className="mt-3 list-disc pl-5 text-sm text-foreground/70">
          {result.call_to_action.map((item, i) => <li key={i}>{item}</li>)}
        </ul>
      )}
      <div className="mt-6 space-y-3">
        {FAIRNESS_SECTION_ORDER.map((rating) => (
          <ClauseSection key={rating} rating={rating} clauses={grouped[rating]} />
        ))}
      </div>
      <Link href="/evaluate-contract" className={BACK_LINK}>
        Evaluate another contract
      </Link>
    </article>
  );
}

function NotAContract({ summary }: { summary: string | null }) {
  return (
    <div className={PAGE_CONTAINER}>
      <h1 className={PAGE_TITLE}>Not a contract</h1>
      <p className="mt-2 text-foreground/60">{summary || 'The uploaded document does not appear to be a contract.'}</p>
      <Link href="/evaluate-contract" className={BACK_LINK}>
        Try another document
      </Link>
    </div>
  );
}

function EvaluationFailed({ message }: { message: string }) {
  return (
    <div className={PAGE_CONTAINER}>
      <h1 className={PAGE_TITLE}>Evaluation failed</h1>
      <p className="mt-2 text-foreground/60">{message}</p>
      <Link href="/evaluate-contract" className={BACK_LINK}>
        Try again
      </Link>
    </div>
  );
}

export default function ContractPage() {
  const { id } = useParams<{ id: string }>();
  const [review, setReview] = useState<ReviewResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notFound, setNotFound] = useState(false);
  const [statusText, setStatusText] = useState('Preparing evaluation...');

  useEffect(() => {
    let cancelled = false;
    const controller = new AbortController();
    const start = Date.now();

    async function fetchAndPoll() {
      try {
        while (!cancelled && Date.now() - start < POLL_TIMEOUT) {
          const res = await fetch(`${BACKEND_URL}/api/contracts/${id}/review`, {
            signal: controller.signal,
          });
          if (res.status === 404) {
            setNotFound(true);
            setLoading(false);
            return;
          }
          if (!res.ok) throw new Error('Failed to fetch review');
          const data = ReviewResponseSchema.parse(await res.json());
          setReview(data);
          if (data.status === 'completed' || data.status === 'failed') {
            setLoading(false);
            return;
          }
          setStatusText(STATUS_TEXT[data.status] || 'Processing...');
          await new Promise((r) => setTimeout(r, POLL_INTERVAL));
        }
        if (!cancelled) {
          setError('Evaluation timed out — please try again');
          setLoading(false);
        }
      } catch (e) {
        if (!cancelled) {
          if (e instanceof DOMException && e.name === 'AbortError') return;
          setError('Connection error — please check your network and try again');
          setLoading(false);
        }
      }
    }

    fetchAndPoll();
    return () => {
      cancelled = true;
      controller.abort();
    };
  }, [id]);

  if (loading) return <LoadingState statusText={statusText} />;
  if (notFound) return <NoEvaluation />;
  if (error) return <EvaluationFailed message={error} />;
  if (!review) return <NoEvaluation />;
  if (review.status === 'failed') return <EvaluationFailed message={review.failure_message || 'Evaluation failed'} />;
  if (review.status === 'completed') {
    if (review.overall_fairness) return <EvaluationResults result={review} />;
    return <NotAContract summary={review.summary} />;
  }
  return <LoadingState statusText={statusText} />;
}

'use client';

import { useState } from 'react';
import type { FairnessRating, ReviewClause } from '@/app/evaluate-contract/types';
import { getFairnessDisplay } from '@/app/evaluate-contract/fairness-utils';
import ClauseCard from './ClauseCard';

const SECTION_BORDER = 'rounded-lg border border-foreground/10 px-4 py-3';
const SECTION_HEADER = `flex w-full items-center justify-between ${SECTION_BORDER} text-left hover:bg-foreground/5`;
const CLAUSE_LIST = 'mt-2 max-h-[50vh] space-y-2 overflow-y-auto';

function NoClauses({ rating, label }: { rating: FairnessRating; label: string }) {
  const isCelebratory = rating !== 'fair';
  const icon = isCelebratory ? '✓' : '⚠';
  const text = isCelebratory
    ? `No ${label.toLowerCase()} clauses`
    : 'No fair clauses found';

  return (
    <div className={`flex items-center gap-2 ${SECTION_BORDER} text-foreground/50`}>
      <span>{icon}</span>
      <span>{text}</span>
    </div>
  );
}

function ExpandableClauses({ label, clauses }: { label: string; clauses: ReviewClause[] }) {
  const [expanded, setExpanded] = useState(false);

  return (
    <section aria-label={`${label} clauses`}>
      <button
        type="button"
        onClick={() => setExpanded(!expanded)}
        aria-expanded={expanded}
        className={SECTION_HEADER}
      >
        <span className="font-semibold">{label} ({clauses.length})</span>
        <span className="text-foreground/40">{expanded ? '−' : '+'}</span>
      </button>
      {expanded && (
        <ul className={CLAUSE_LIST}>
          {clauses.map((clause) => (
            <li key={clause.section_number}>
              <ClauseCard clause={clause} />
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

interface ClauseSectionProps {
  rating: FairnessRating;
  clauses: ReviewClause[];
}

export default function ClauseSection({ rating, clauses }: ClauseSectionProps) {
  const { label } = getFairnessDisplay(rating);

  if (clauses.length === 0) {
    return <NoClauses rating={rating} label={label} />;
  }

  return <ExpandableClauses label={label} clauses={clauses} />;
}

'use client';

import { useRef, useState } from 'react';
import {
  ALLOWED_EXTENSIONS,
  validateFileExtension,
  validateFileSize,
} from './validation';

interface FileDropZoneProps {
  file: File | null;
  onFileChange: (file: File | null) => void;
}

function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export function FileDropZone({ file, onFileChange }: FileDropZoneProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const dragCounter = useRef(0);

  function processFile(incoming: File) {
    setError(null);

    if (!validateFileExtension(incoming.name)) {
      setError(
        `File type not allowed. Accepted formats: ${ALLOWED_EXTENSIONS.join(', ')}`,
      );
      return;
    }

    if (!validateFileSize(incoming.size)) {
      setError('File is too large. Maximum size is 10 MB.');
      return;
    }

    onFileChange(incoming);
  }

  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
    const selected = e.target.files?.[0];
    if (selected) processFile(selected);
  }

  function handleRemove() {
    onFileChange(null);
    if (inputRef.current) inputRef.current.value = '';
  }

  function handleDragEnter(e: React.DragEvent) {
    e.preventDefault();
    dragCounter.current++;
    if (!isDragging) setIsDragging(true);
  }

  function handleDragOver(e: React.DragEvent) {
    e.preventDefault();
  }

  function handleDragLeave(e: React.DragEvent) {
    e.preventDefault();
    dragCounter.current--;
    if (dragCounter.current === 0) setIsDragging(false);
  }

  function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    dragCounter.current = 0;
    setIsDragging(false);
    const dropped = e.dataTransfer.files[0];
    if (dropped) processFile(dropped);
  }

  if (file) {
    return (
      <div className="flex items-center justify-between rounded-lg border border-foreground/20 p-4">
        <div>
          <p className="font-medium">{file.name}</p>
          <p className="text-sm text-foreground/60">
            {formatFileSize(file.size)}
          </p>
        </div>
        <button
          type="button"
          onClick={handleRemove}
          className="rounded-md px-3 py-1 text-sm text-foreground/60 hover:bg-foreground/10"
        >
          Remove
        </button>
      </div>
    );
  }

  return (
    <div
      onDragEnter={handleDragEnter}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={`flex flex-col items-center justify-center rounded-lg border-2 border-dashed p-12 text-center ${
        isDragging ? 'border-blue-400 bg-blue-50/10' : 'border-foreground/20'
      }`}
    >
      <p className="text-foreground/60">Drag and drop your contract here</p>
      <p className="mt-2 text-sm text-foreground/40">or</p>
      <button
        type="button"
        onClick={() => inputRef.current?.click()}
        className="mt-2 rounded-md bg-foreground/10 px-4 py-2 text-sm font-medium hover:bg-foreground/20"
      >
        Browse files
      </button>
      {error && <p className="mt-3 text-sm text-red-500">{error}</p>}
      <input
        ref={inputRef}
        type="file"
        aria-label="Upload contract file"
        accept={ALLOWED_EXTENSIONS.join(',')}
        className="hidden"
        onChange={handleInputChange}
      />
    </div>
  );
}

